package com.shopsphere;import static org.junit.jupiter.api.Assertions.*;import java.math.BigDecimal;import java.util.*;import org.junit.jupiter.api.*;class ProductServiceTest{ProductService service;@BeforeEach void set(){service=new ProductService(new ProductRepository.InMemory());}ProductDtos.Request req(String sku,String name,String category,BigDecimal price){return new ProductDtos.Request(sku,name,name.toLowerCase().replace(" ","-"),"Premium product", "Orion",category,price,price.multiply(BigDecimal.valueOf(1.2)),BigDecimal.TEN,4.6,12,List.of("/image.jpg"),Map.of("Color","Black"),true);}@Test void createGetAndSearch(){Product p=service.create(req("SKU-1","Nova Phone","Mobiles",BigDecimal.valueOf(50000)));service.create(req("SKU-2","Aero Laptop","Laptops",BigDecimal.valueOf(90000)));assertEquals(p,service.get(p.id()));assertEquals(1,service.search("nova",null,null,null,null,null,"newest",0,10).totalElements());assertEquals(1,service.search(null,"Laptops",null,BigDecimal.valueOf(80000),null,4.0,"price_asc",0,10).totalElements());}@Test void searchIsTrimmedCaseInsensitivePartialAndMultiWord(){service.create(req("SKU-1","Classic Cargo Pants","Fashion",BigDecimal.valueOf(2500)));assertEquals(1,service.search("  CARGO pants  ",null,null,null,null,null,"relevance",0,10).totalElements());assertEquals(1,service.search("argo pan",null,null,null,null,null,"relevance",0,10).totalElements());assertEquals(1,service.search("fashion",null,null,null,null,null,"relevance",0,10).totalElements());assertEquals(0,service.search("cargo laptop",null,null,null,null,null,"relevance",0,10).totalElements());}@Test void duplicateSkuRejected(){service.create(req("SKU-1","One","Mobiles",BigDecimal.TEN));assertThrows(ConflictException.class,()->service.create(req("SKU-1","Two","Mobiles",BigDecimal.TEN)));}}
